-module(beam_prim_file_encoding410).
-export([run/0,run_stacks/0,worker/2]).
cases() -> [to_empty,to_ascii,to_nested,to_utf8,to_invalid_utf8,to_supplementary_binary,to_surrogate_list,to_supplementary_list,to_zero_list,to_zero_binary,to_atom,to_improper,to_nested_binary,to_bitstring,from_empty,from_ascii,from_surrogate,from_odd,from_terminator,from_atom,norm_empty,norm_ascii,norm_acute,norm_hangul,norm_supplementary,norm_invalid,norm_atom,trans_empty,trans_valid,trans_invalid,trans_zero,trans_list,normalization_trie].
run() -> [{Case,observe(Case)} || Case <- cases()].
run_stacks() -> [with_depth(Depth) || Depth <- [default,0,1,2,8]].
with_depth(default) -> {default,run()};
with_depth(Depth) -> Old=erlang:system_flag(backtrace_depth,Depth), try {Depth,run()} after erlang:system_flag(backtrace_depth,Old) end.
observe(Case) ->
    Parent=self(), Ref=make_ref(), {Pid,Mon}=spawn_monitor(?MODULE,worker,[{Parent,Ref},Case]),
    receive {Ref,Value} -> receive {'DOWN',Mon,process,Pid,normal} -> Value end end.
worker({Parent,Ref},Case) ->
    Outcome=try probe(Case) of Value -> {value,Value} catch Class:Reason:Stack -> {caught,Class,Reason,Stack} end,
    Parent ! {Ref,Outcome}.
probe(to_empty) -> prim_file:internal_name2native([]);
probe(to_ascii) -> prim_file:internal_name2native([65,66]);
probe(to_nested) -> prim_file:internal_name2native([65,[8364],[]]);
probe(to_utf8) -> prim_file:internal_name2native(<<195,169>>);
probe(to_invalid_utf8) -> prim_file:internal_name2native(<<255>>);
probe(to_supplementary_binary) -> prim_file:internal_name2native(<<240,159,152,128>>);
probe(to_surrogate_list) -> prim_file:internal_name2native([55296]);
probe(to_supplementary_list) -> prim_file:internal_name2native([128512]);
probe(to_zero_list) -> prim_file:internal_name2native([65,0,66]);
probe(to_zero_binary) -> prim_file:internal_name2native(<<65,0,66>>);
probe(to_atom) -> prim_file:internal_name2native(atom);
probe(to_improper) -> prim_file:internal_name2native([65|66]);
probe(to_nested_binary) -> prim_file:internal_name2native([<<65>>]);
probe(to_bitstring) -> prim_file:internal_name2native(<<1:1>>);
probe(from_empty) -> prim_file:internal_native2name(<<>>);
probe(from_ascii) -> prim_file:internal_native2name(<<65,0,66,0>>);
probe(from_surrogate) -> prim_file:internal_native2name(<<0,216>>);
probe(from_odd) -> prim_file:internal_native2name(<<65,0,255>>);
probe(from_terminator) -> prim_file:internal_native2name(<<65,0,0,0>>);
probe(from_atom) -> prim_file:internal_native2name(atom);
probe(norm_empty) -> prim_file:internal_normalize_utf8(<<>>);
probe(norm_ascii) -> prim_file:internal_normalize_utf8(<<65>>);
probe(norm_acute) -> prim_file:internal_normalize_utf8(<<101,204,129>>);
probe(norm_hangul) -> prim_file:internal_normalize_utf8(<<4352/utf8,4449/utf8>>);
probe(norm_supplementary) -> prim_file:internal_normalize_utf8(<<128512/utf8>>);
probe(norm_invalid) -> prim_file:internal_normalize_utf8(<<255>>);
probe(norm_atom) -> prim_file:internal_normalize_utf8(atom);
probe(trans_empty) -> prim_file:is_translatable(<<>>);
probe(trans_valid) -> prim_file:is_translatable(<<195,169>>);
probe(trans_invalid) -> prim_file:is_translatable(<<255>>);
probe(trans_zero) -> prim_file:is_translatable(<<0>>);
probe(trans_list) -> prim_file:is_translatable([65]);
probe(normalization_trie) ->
    [{Points,prim_file:internal_normalize_utf8(list_to_binary([<<Point/utf8>> || Point <- Points]))} || {Points,_Expected} <- vectors()].
